INSERT OR IGNORE INTO books (id, title, subtitle, author, series, seriesOrder, description, fullDescription, bookPages, genre, publicationStatus, publicationDate, isbn, bookFormat, purchaseLink, amazonLink, googlePlayBooksLink, featuredBook, hardcoverAvailable, paperbackAvailable, eBookAvailable, audiobookAvailable, signedCopyAvailable, signedHardcoverPrice, signedPaperbackPrice, directOrderInstructions, signedCopyContactEmail, signedCopyInstructions, signedContactEmail, slug, coverUrl) VALUES
('0f875b68-defb-4e28-8e6e-84253b40a196', 'The Empire 2', 'Buried Sun', 'R.E. Smith', 'The Empire', '2.0', 'The war that began in Rising Sun has changed the balance of power, but victory has not brought peace. As rival rulers fight over a buried city and its ancient technology, the past threatens to reshape every kingdom above it.', '<p class="font_8">The Buried Sun</p>
<p class="font_8"><strong>Book Two of The Empire</strong></p>
<p class="font_8"><strong>Some ruins are buried because the dead deserve peace. Others are buried because the living are afraid of what they might remember.</strong></p>
<p class="font_8">The war that began in <em>Rising Sun</em> has changed the balance of power, but victory has not brought peace.</p>
<p class="font_8">Arslan, Xu, Yuelan, and the people caught between their worlds now face the consequences of rebellion, fractured alliances, and ancient forces awakened beneath the earth. The old order is breaking, and every kingdom is scrambling to decide what comes next.</p>
<p class="font_8">Then the buried city begins to wake.</p>
<p class="font_8">Beneath forgotten roads and sealed chambers lies evidence of a civilization older than the empires now fighting above it. Its machines were built for purposes no living ruler fully understands. Its history contradicts sacred stories. Its weapons could alter the balance of power overnight.</p>
<p class="font_8">And everyone wants control of what has been found.</p>
<p class="font_8">As soldiers move across unstable borders, rulers bargain over survival, families are divided by loyalty, and old enemies become necessary allies. The deeper the excavation goes, the clearer one truth becomes:</p>
<p class="font_8">The past was not lost.</p>
<p class="font_8">It was hidden.</p>
<p class="font_8"><strong>The Buried Sun</strong> is the second book in <em>The Empire</em>, a completed nine-book adult epic fantasy series of war, political intrigue, ancient technology, dragons, rebellion, love, loyalty, and the brutal cost of building a new world from the ruins of the old.</p>
<p class="font_8">For readers who enjoy sprawling political fantasy, buried civilizations, morally complicated characters, military conflict, dangerous archaeology, ancient mysteries, and empires shaped by secrets no one was meant to uncover.</p>
<p class="font_8"><strong>The sun did not die.<br>
It was buried.</strong></p>', '491', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2026-11-01T04:00:00Z', '9798194920303', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0HGL48K2W', 'https://www.amazon.com/dp/B0HGL48K2W', '', 0, 0, 0, 0, 0, 0, '32.0', '17.0', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('1091014e-27e1-42b3-9721-9925fc609672', 'Serpent City', 'When the City Wakes, the Serpent Rises', 'R.E. Smith', '', '', 'Beneath New York, artist Rosa Navarro discovers that something ancient is changing her paintings and knows her name. Drawn into abandoned tunnels and a hidden world of shifting reality, she must decide whether the serpent below the city wants her as prey or as its chosen vessel.', '<p class="font_8"><em>An Ancient Hunger in the City That Never Sleeps</em></p>
<p class="font_8">Beneath New York’s crowded streets, something ancient stirs.</p>
<p class="font_8">Rosa Navarro has always lived with shadows — in her art, her dreams, and the city’s forgotten corners. But when the faces in her paintings begin to change, twisting into visions she can’t explain, Rosa is drawn into a hidden world beneath the skyline. There, in the abandoned tunnels and derelict stations of the city’s bones, she finds whispers of a serpent older than history… and the chilling truth that it knows her name.</p>
<p class="font_8">As reality fractures and the line between dream and waking blurs, Rosa and her friends are pulled into a game they don’t understand, stalked by an ageless presence that feeds on memory, desire, and fear.</p>
<p class="font_8">The deeper they go, the more the city itself changes — murals shift, buildings breathe, and the serpent waits in every reflection. To survive, Rosa must face the thing beneath the streets… and decide whether she is its prey, or its chosen vessel.</p>
<p class="font_8">Perfect for fans of <strong>Neil Gaiman, Leigh Bardugo, and urban legends with teeth</strong>, <em>Serpent City</em> is a haunting blend of supernatural horror and gritty urban fantasy that will keep you turning pages deep into the night.</p>', '234', 'Mystery / Thrillers & Suspense / Supernatural / General', 'Available', '2025-08-12T04:00:00Z', '9798275424447', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0FM5W93KY', 'https://www.amazon.com/dp/B0FM5W93KY', '', 0, 1, 1, 1, 0, 0, '17.76', '9.28', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('1c2b247e-a580-4c9b-8519-9b59103f547f', 'The Empire Prequel 5', 'The Iron Exile', 'R.E. Smith', 'The Empire Prequel', '5.0', 'An unproven accusation sends an exile into a dangerous search for the truth. When contradictory records and a missing bronze key point north, old secrets threaten to expose the fragile foundations of the world before the Empire.', '<p class="font_8">The Iron Exile<br>
<br>
Book Five of The Empire Prequel<br>
<br>
The accusation was never proved. The exile survived it anyway.<br>
<br>
A missing bronze key should have been an inventory problem.<br>
<br>
Instead, contradictory records point north.<br>
<br>
One old transfer sheet mentions Temür bronze. Another does not. A copied note suggests a missing register key may have traveled with repair material decades earlier. No one can prove it.<br>
<br>
That is enough to begin a review.<br>
<br>
The review becomes an audit.<br>
<br>
The audit becomes suspicion.<br>
<br>
And suspicion begins moving families.<br>
<br>
At first, the language remains careful.<br>
<br>
Not expulsion.<br>
<br>
Review relocation.<br>
<br>
Not confiscation.<br>
<br>
Examination.<br>
<br>
Not guilt.<br>
<br>
Restricted bronze.<br>
<br>
Each phrase is defensible.<br>
<br>
Together, they become a machine.<br>
<br>
As workshops close and households are moved, Iron Hearth fills with smiths, children, widows, tools, wagons, records, and people who never planned to become part of anything larger than survival.<br>
<br>
From a distant office, the settlement looks different.<br>
<br>
A concentration.<br>
<br>
A technical center.<br>
<br>
Eventually, a fortress.<br>
<br>
On the ground, it is workshops, cooking fires, crowded latrines, cousins, debts, children, and one goat standing on a wall someone has labeled defensive works.<br>
<br>
Orun Temür knows the danger of records.<br>
<br>
His family has spent generations preserving them.<br>
<br>
Now the state uses that very continuity against him.<br>
<br>
When an official offers to remove Ayla, Arslan, Saran, and their household from relocation review in exchange for one bronze calibration key, the offer contains no threat.<br>
<br>
That makes it worse.<br>
<br>
Meanwhile, relocation itself becomes an industry.<br>
<br>
Wagons.<br>
<br>
Storage.<br>
<br>
Certified transport.<br>
<br>
Approved inspectors.<br>
<br>
Replacement craftsmen.<br>
<br>
Nothing requires corruption.<br>
<br>
Once displacement has a price, someone can always build a business around moving people.<br>
<br>
Then Iron Hearth burns.<br>
<br>
Families scatter.<br>
<br>
Archives officials expected to seize turn out never to have existed in one place. Household records leave beneath blankets beside onions. Children carry spoons, bent nails, and whatever pieces of home fit inside a wagon.<br>
<br>
And when the investigation finally weakens, the damage does not politely reverse itself.<br>
<br>
The accusation was not proved.<br>
<br>
The dispersal remains.<br>
<br>
Now the state must confront a harder question:<br>
<br>
What does justice look like after return becomes possible?<br>
<br>
Some people want their homes.<br>
<br>
Some want compensation.<br>
<br>
Some want graves.<br>
<br>
Some want workshops but not residence.<br>
<br>
Some can return and choose not to.<br>
<br>
Because the right to go home means very little if someone else gets to decide that home is still where you belong.<br>
<br>
The Iron Exile is Book Five of The Empire Prequel, continuing the six-book story of how investigation becomes policy, policy becomes displacement, and institutions can preserve injustice long after the original accusation collapses.<br>
<br>
For readers who enjoy political epic fantasy, family sagas, legal systems, forced relocation, contested evidence, ancient technology, institutional power, dry humor, moral complexity, and stories where the most dangerous sentence may be the one everyone agrees sounds reasonable.<br>
<br>
They searched for one missing key.<br>
They found an entire people easier to move.</p>', '590', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2027-11-01T04:00:00Z', '9798176942637', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0HL4SPFXJ', 'https://www.amazon.com/dp/B0HL4SPFXJ', '', 0, 0, 0, 0, 0, 0, '', '', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('22258138-f43e-42a5-9d50-dedb568a3341', 'The Cries Beneath the Floorboards', 'The Story of Amelia Dyer', 'R.E. Smith', '', '', 'London, 1896. Willowbrook House, a once-respectable orphanage, hides locked doors and whispered horrors beneath its Victorian gentility. As the darkness beneath the floorboards stirs, the children and caretakers face a threat that polite society would rather keep buried.', '<p class="font_8"><strong>The Cries Beneath the Floorboards</strong><br>
<em>By R. E. Smith</em></p>
<p class="font_8"><strong>Beneath the lace and lullabies of Victorian England, something monstrous stirs…</strong></p>
<p class="font_8">London, 1896. The fog hangs thick over Willowbrook House, a once-genteel orphanage now cloaked in whispered rumors and locked doors. Infants vanish in the night. Hollow-eyed matrons speak in hushed tones. And under the floorboards—where the boards creak and the air grows cold—the cries of the forgotten echo still.</p>
<p class="font_8">When young constable Edwin Harrow is called to investigate the mysterious deaths surrounding the home, he uncovers far more than criminal neglect. Beneath the orphanage lies a deeper horror—a secret buried in silence, stitched with deception, and soaked in blood.</p>
<p class="font_8">This is the tale of Amelia Dyer, a woman cloaked in civility and corsets, whose cradle arms once comforted but now conceal. A tale inspired by the real-life "Ogress of Reading," whose crimes rattled an empire and tested the limits of human evil.</p>
<p class="font_8"><strong>What drives a woman to murder the most innocent among us?</strong><br>
<strong>And why do some sins refuse to stay buried?</strong></p>
<p class="font_8">Told in chilling prose and shadowed with historical authenticity, <em>The Cries Beneath the Floorboards</em> is a gothic psychological horror that peels back the wallpaper of Victorian respectability—and finds a bloodstained nursery underneath.</p>', '57', 'British & Irish / 19th Century / Women in History', 'Available', '2025-08-03T04:00:00Z', '9798275567311', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0FL12FXM9', 'https://www.amazon.com/dp/B0FL12FXM9', '', 1, 1, 1, 1, 0, 0, '13.33', '6.6', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('315db67f-aa7b-45bf-865c-5c64bd55c34a', 'Hodge', 'Where No Man Commands Belief', 'R.E. Smith', '', '', 'Cast across the sea, Hodge believes faith should belong to conscience, not be controlled by magistrates, ministers, or powerful men. In the New World, his ideas meet a society unwilling to accept them easily, forcing him to confront the cost of conviction and independence.', '<p class="font_8">Before a man can build a world he must first be thrown out of the old one.</p>
<p class="font_8">Hodge travels across the sea. He thinks that faith should be a thing, not controlled by magistrates, ministers or men in power.. The New World does not accept gentle ideas. It challenges them.</p>
<p class="font_8">From the darkness under a ships deck to the tough settlements in a harsh wilderness Hodge sees sickness, fear, judgment, pride and the quiet cruelty that men do when they think God is on their side. Among settlers who are just trying to survive and leaders who want to control what people believe one question starts to matter more than all the others:</p>
<p class="font_8">Who has the right to tell another man what to believe?</p>
<p class="font_8">This story is inspired by the life and ideas of Roger Williams. It is about Hodges journey and the struggle for liberty in early America.</p>
<p class="font_8">As Hodge stands up against the powers of his time he risks losing his family, safety, reputation and home. What starts as a disagreement becomes an accusation. What starts as a matter of conscience becomes a rebellion. And when those in power finally decide there is no place for him among them Hodge must walk into the wilderness with nothing but his conviction, uncertainty and the strong belief that no man should come between another persons soul and God.</p>
<p class="font_8">This novel is for readers who enjoy stories, about people, early American history, moral conflict, surviving in the wilderness and ordinary men who are forced to take a stand. It explores what it costs to be free before freedom was a concept.</p>
<p class="font_8">They thought they had thrown him out.</p>
<p class="font_8">What they had done was set him free.</p>', '537', 'History / General / 18th Century', 'Available', '2026-05-08T04:00:00Z', '9798196026591', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GZY8QTMR', 'https://www.amazon.com/dp/B0GZY8QTMR', '', 1, 1, 1, 1, 0, 0, '22.36', '14.61', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('327bf0e7-b838-4d31-a0af-f97519f53cd5', 'The Sink', 'YOU DON’T LEAVE THE WOODS CLEAN', 'R.E. Smith', '', '', 'Roy and Lisa set out for a straightforward day of kayaking, expecting quiet water, laughter, and an ordinary adventure. But the river offers more than they planned, turning a familiar outing into a test of courage, partnership, and survival.', '<p class="font_8">A simple day on the river was supposed to be the easy kind of tired.<br>
<br>
Roy and Lisa push their kayaks into quiet water with the kind of confidence that comes from years of doing hard things together. The plan is straightforward: a clean run, a few laughs, a little sunshine, and home before it’s fully dark.<br>
Then the current starts making decisions for them.<br>
<br>
A wrong turn becomes a trap. Familiar water turns strange. The banks close in. The light goes thin. Little problems stack into big ones—gear, fatigue, cold, distance, time—and the river stops feeling like a place you pass through and starts feeling like something that’s watching you back.<br>
<br>
As the day bleeds into night, Roy and Lisa have to do what long-time partners do best: communicate when they’re scared, stay sharp when they’re exhausted, and keep moving when standing still feels safer. Every choice has a cost. Every delay narrows the options. And what began as a bad kayak trip becomes a fight to make it out with their bodies—and their bond—still intact.<br>
<br>
<strong>The Sink: You Don’t Leave the Woods Clean</strong> is a tense wilderness thriller about endurance, marriage under pressure, and the quiet terror of realizing the river doesn’t care how prepared you thought you were.</p>', '93', 'General / Suspense / Domestic', 'Available', '2026-02-01T05:00:00Z', '9798241207173', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GCG785LM', 'https://www.amazon.com/dp/B0GCG785LM', '', 1, 1, 1, 1, 0, 0, '13.33', '6.6', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('3445059d-7609-4ef8-ab98-ae3d0bf44479', 'Crown of Cinders 2', 'The Ash Accords', 'R.E. Smith', 'Crown of Cinders', '2.0', 'After Kethria’s throne-city burns, Sable discovers that peace can be more dangerous than war. As rulers trade in bargains and old debts demand payment, the struggle for power moves from open battle into the shadows of the recovering city.', '<p class="font_8">The ash never settles in Kethria. It just waits.</p>
<p class="font_8">After the throne-city burned and the first debts were paid in blood, <strong>Sable</strong> learns a brutal truth: war is loud, but <em>peace</em> is where the real knives come out. Kings don’t rule with crowns—they rule with bargains. And bargains, in Kethria, are written in ash.</p>
<p class="font_8">With the realm splintering, rival houses circling, and dragons choosing sides for reasons no council dares admit, a new treaty is demanded: <strong>the Ash Accords</strong>—a set of laws meant to stop the bleeding… and secretly decide who gets to keep the knife.</p>
<p class="font_8">But someone is forging the marks.</p>
<p class="font_8">As paranoia thickens and the streets fill with smoke and whispers, Sable is forced into the deadliest role of all: not soldier, not hero, but <strong>enforcer of a peace she doesn’t trust</strong>. Every signature costs something. Every concession buys another enemy. And in the shadows, <strong>Rook Calver</strong> moves where oaths can’t reach—hunting the truth behind the Accords, and discovering that the city’s oldest powers never died. They simply learned to wear new faces.</p>
<p class="font_8">Because Kethria doesn’t owe peace.</p>
<p class="font_8"><strong>It owes blood.</strong></p>
<p class="font_8"><strong>CROWN OF CINDERS: THE ASH ACCORDS</strong> is Book Two of the Crown of Cinders series—dark epic fantasy packed with ruthless politics, dragon-fire consequences, and a world where every promise is a weapon.</p>
<p class="font_8"><em>Perfect for readers who love grimdark intrigue, high-stakes alliances, and characters who win by paying the price.</em></p>', '432', 'Epic / Dark Fantasy / Sword & Sorcery', 'Available', '2026-02-01T05:00:00Z', '9798242620933', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GKYD71JX', 'https://www.amazon.com/dp/B0GKYD71JX', '', 0, 1, 1, 1, 0, 0, '20.02', '12.27', '<p>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('36de4574-d6d1-4ca5-a277-9eeca9f482c9', 'Wolves of Tiber 1', 'Bloodborn Kings', 'R.E. Smith', 'Wolves of Tiber', '1.0', 'Rome is gripped by a purity crusade, with priests preaching righteousness while powerful families plot behind closed doors. In the ruined districts, the Bloodborn and their allies are caught in a struggle over faith, power, and who gets to decide what counts as monstrous.', '<p class="font_8">Rome smells like incense and blood—sometimes in the same breath.<br>
A purity crusade is sweeping the streets. Priests preach righteousness while patrician houses sharpen knives behind velvet curtains. In the ruin belt—where the city’s broken bones still jut from the earth—something old watches Rome with the patience of stone.<br>
Two boys are born at the center of it: <strong>Aurelio and Remo</strong>, twins marked by a secret no one in the city is ready to name. Raised in a world that kills children for rumors, they learn early that truth isn’t what’s spoken—it’s what survives.<br>
When the twins come of age, Rome is already cracking. A girl with a strategist’s mind and a predator’s nerve, <strong>Cassia</strong>, is pulled into the storm. A monster in the ruins, <strong>Nera</strong>, circles closer. And deep in the halls of power, ledgers and seals decide who gets to live clean… and who gets to die condemned.<br>
A king sits on a fragile throne.<br>
The Bloodborn are rising.<br>
And Rome is about to learn what it costs to be saved.</p>', '540', 'Genre Fiction / Horror / Dark Fantasy / Epic / Historical', 'Available', '2026-01-01T05:00:00Z', '9798279241347', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GB3GG1CL', 'https://www.amazon.com/dp/B0GB3GG1CL', '', 0, 1, 1, 1, 0, 0, '20.12', '12.37', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('3803bcfa-7f5b-4b4e-b451-73efc6b4f9b6', 'Blood of Eden', 'Book One of The Lilith Covenant', 'R.E. Smith', 'The Lilith Covenant', '', 'Children vanish beneath Castle Noctivar, red bells ring at night, and Lilith remains hungry beneath the mountain. Sevrin Veyr has spent his life obeying his house’s blood laws, but his life among mortals draws him toward secrets that could threaten the vampire order.', '<p class="font_8">Children vanish beneath Castle Noctivar.<br>
Red bells ring in the night.<br>
And in the dark below the mountain, Lilith is still hungry.<br>
Sevrin Veyr has spent his life obeying the blood laws of his house. Under the name Tomas Rill, he walks among mortals as a simple bread runner, stealing infants from their cradles and delivering them beneath six loaves of black bread to the mountain stronghold of Noctivar. He does not ask why. He does not look too closely. In his world, obedience keeps monsters alive.<br>
Then he meets Eliane.<br>
Marked by the castle, armed with white magic, and dangerous enough to kill the men sent to collect her, Eliane should have been another offering. Instead, she becomes the first person to make Sevrin question the kingdom he serves, the blood he carries, and the lullaby every vampire child is taught to fear.<br>
Together with an ancient priest who knows far more than any holy man should, Sevrin and Eliane descend into the red dark beneath Noctivar, where children sleep under poppy blood, vampires worship Baal, and Lilith waits in her bath of stolen life.<br>
Beautiful. Merciless. Older than Eden.<br>
To break her power, Sevrin must face the truth of his father’s sin, the horror of his own obedience, and the forbidden bond growing between him and the woman he was never meant to save.<br>
But Lilith does not merely want blood.<br>
She wants a door.<br>
And love may open it.<br>
Blood of Eden is a dark gothic vampire novel blending biblical horror, forbidden romance, ancient myth, blood magic, and the terrifying legend of Lilith. Perfect for readers who enjoy seductive monsters, cursed bloodlines, morally gray heroes, dangerous heroines, and horror that bites deep.</p>', '299', 'Dark Fantasy / Horror › Vampires / Occult & Supernatural', 'Available', '2026-06-28T04:00:00Z', '9798184766324', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H6VQZ8FK', 'https://www.amazon.com/dp/B0H6VQZ8FK', '', 0, 1, 1, 1, 0, 0, '17.95', '10.95', '<p>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('50f74688-1599-481b-aff6-511e41d4eb1c', 'Von Stockhausen', 'Anna Maria’s Story', 'R.E. Smith', '', '', 'Anna Maria is born into a world where servants are disposable and silence is expected. Inside an old European household, she learns the rules that govern power, class, and survival, while the name Von Stockhausen reveals a price far greater than its noble sound suggests.', '<p class="font_8">**VON STOCKHAUSEN** is a name that sounds noble—until you learn what it cost to wear it.<br>
<br>
Anna Maria is born into a world that treats servants as disposable and silence as virtue. In the cold corridors of an old European household, she learns the rules that keep a girl alive: work hard, speak little, and never let anyone see what you want.<br>
<br>
But wanting is dangerous.<br>
<br>
When a whisper becomes an accusation, the village doesn’t hunt for truth. It hunts for certainty. Faith turns sharp. Neighbors turn watchful. And the same hands that once accepted her labor begin reaching for rope, fire, and a clean story they can tell themselves afterward.<br>
<br>
**Von Stockhausen: Anna Maria’s Story** is a bleak, intimate work of historical horror—where the real terror isn’t a creature in the forest, but what ordinary people become when fear gives them permission.<br>
<br>
If you like **atmospheric dread**, **period grit**, and stories where **survival is stubborn, not glamorous**, step into the dark and meet Anna Maria.<br>
<br>
**Scroll up and grab your copy today.**</p>', '341', 'Fiction / Gothic / Medieval', 'Available', '2025-12-27T05:00:00Z', '9798241421098', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GC3XVTRX', 'https://www.amazon.com/dp/B0GC3XVTRX', '', 0, 1, 1, 1, 0, 0, '17.08', '10.79', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('57a54f0c-7cd1-43ec-9ba2-1ffcbedb6f02', 'The Empire Prequel 1', 'The White Stag', 'R.E. Smith', 'The Empire Prequel', '1.0', 'Before the Empire, a harsh winter leaves too many heirs and too little grain. After Bayan Khagan’s death, rival claimants begin changing storehouse seals and competing for control, setting the rules, ambitions, and conflicts that will shape the world to come.', '<p class="font_8">The White Stag</p>
<p class="font_8"><strong>Book One of The Empire Prequel</strong></p>
<p class="font_8"><strong>Before there was an empire, there was a winter with too many heirs and not enough grain.</strong></p>
<p class="font_8">Bayan Khagan is dead.</p>
<p class="font_8">Before his body is cold, storehouse seals begin changing.</p>
<p class="font_8">Aruq wants rules. Qadan wants strength. Kür Qara wants limits no claimant can quietly swallow later. Around them, widows, riders, clerks, herders, smiths, and household leaders discover that succession is not merely a question of blood.</p>
<p class="font_8">It is grain.</p>
<p class="font_8">Roads.</p>
<p class="font_8">Hostages.</p>
<p class="font_8">Pasture.</p>
<p class="font_8">Winter.</p>
<p class="font_8">And who gets to decide which necessity becomes law.</p>
<p class="font_8">As rival claims harden, thousands of displaced people are forced north through dangerous country. Among them is Aysu, carrying a child and trying to keep a refugee column alive while nobles argue over horses and men offer “protection” with recruitment hidden inside it.</p>
<p class="font_8">Then a pale stag appears above White Stag Pass.</p>
<p class="font_8">Some call it Heaven.</p>
<p class="font_8">Others call it a deer.</p>
<p class="font_8">The scouts notice something more useful.</p>
<p class="font_8">Warm ground.</p>
<p class="font_8">The route beneath the animal may be opening because of something buried in the mountain, something older than the rulers fighting over the world above it.</p>
<p class="font_8">Survival turns coincidence into story.</p>
<p class="font_8">Story becomes ritual.</p>
<p class="font_8">Ritual begins becoming law.</p>
<p class="font_8">Years later, an antler that never belonged to an ancient standard is mounted in bronze that was never meant to hold it. Men lower their voices near it. Children inherit a legend built from events that were real, even when the meaning placed around them was not.</p>
<p class="font_8">And beneath the growing myth, the harder questions remain.</p>
<p class="font_8">Can a ruler limit his own authority once people begin asking him to use it?</p>
<p class="font_8">Can emergency power remain temporary?</p>
<p class="font_8">Can a hostage be called a surety without changing what it is?</p>
<p class="font_8">Can ancient machinery be made safe without rebuilding the system it once served?</p>
<p class="font_8">And when a civilization needs a road badly enough, how long before “necessary” becomes permission?</p>
<p class="font_8"><strong>The White Stag</strong> is Book One of <em>The Empire Prequel</em>, the six-book series revealing how the political traditions, ancient infrastructure, laws, legends, and institutional habits of <em>The Empire</em> were created generations before <em>Rising Sun</em>.</p>
<p class="font_8">For readers who enjoy political epic fantasy, succession crises, winter survival, ancient technology, dragons, family conflict, law, mythmaking, dry humor, and characters trying to build systems strong enough to survive themselves.</p>
<p class="font_8"><strong>Every empire begins with a story.<br>
The dangerous part is deciding which version becomes history.</strong></p>', '458', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2027-07-01T04:00:00Z', '9798174957336', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0HK2MVM2C', 'https://www.amazon.com/dp/B0HK2MVM2C', '', 0, 0, 0, 0, 0, 0, '', '', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('6331d87d-56c6-46c2-895c-fb071dcaf272', 'The Hollow Kingdom 4', 'Outside Claim', 'R.E. Smith', 'The Hollow Kingdom', '4.0', 'Tressa Vale has measured impossible roads, waking bells, and a throne no living ruler should hold. Now a buried lane opens, snow falls in the wrong season, and a claim from beyond the kingdom challenges the laws that have kept its hidden powers contained.', '<p class="font_8">**A buried lane opens. Snow falls in the wrong season. And a claim from outside the kingdom begins to speak.**<br>
<br>
Tressa Vale has measured impossible roads, waking bells, and a throne no living ruler should hold.<br>
<br>
But the Hollow Kingdom is changing.<br>
<br>
What began beneath Bellharrow has spread into roads, villages, offices, and old graves the Crown would rather leave sealed. Every place Tressa names becomes harder to ignore. Every witness she protects becomes proof that the old kingdom was built on more than bad law. It was built on silence.<br>
<br>
Now the silence is cracking.<br>
<br>
In Beggar’s Lane, a buried road opens beneath lime, gravel, and denial, revealing the poor who were packed under the royal road and forgotten. In Applecross, snow falls through blooming orchards, warning of a season cut open by force. And at Harrowmere, a black marker splits like an egg, glowing with cold green light and speaking with the voice of Edric Voss.<br>
<br>
The road is lying about distance.<br>
<br>
The toll is being paid in blood, memory, and office.<br>
<br>
And something outside the known order is learning how to claim its way in.<br>
<br>
Garran Holt remains at Tressa’s side, wounded, stubborn, and far too ready to spend himself if it keeps her standing. Their bond is no longer easy to deny, but love in the Hollow Kingdom is not a soft refuge. It is a pressure point. A danger. A promise with teeth.<br>
<br>
To hold the line, Tressa must decide which claims deserve entry, which ones deserve refusal, and how much of herself she can give before the road mistakes her for a door.<br>
<br>
**The Outside Claim** is Book Four of **The Hollow Kingdom**, a dark romantasy series of haunted roads, ancient bells, buried justice, dangerous magic, sharp banter, slow-burn devotion, and a kingdom that refuses to stay under the Crown’s boot.</p>', '310', 'Dark Romance / Gothic / Romantasy', 'Available', '2026-06-22T04:00:00Z', '9798183765168', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H6CNP1L9', 'https://www.amazon.com/dp/B0H6CNP1L9', '', 0, 1, 1, 1, 0, 0, '31.99', '21.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('654788f7-2f39-4d7f-a234-4a5cef2ad236', 'The Hollow Kingdom 9', 'Season Wound', 'R.E. Smith', 'The Hollow Kingdom', '9.0', 'The year is breaking, dragons are answering, and the Crown Chain waits at the heart of a wound in the seasons. Tressa Vale must follow a road that crosses time itself and confront the forces behind the Hollow Kingdom’s unraveling order.', '<p class="font_8">**The year is breaking. The dragons are answering. And the Crown Chain waits at the heart of the wound.**<br>
<br>
Tressa Vale has followed wrong roads, hidden roads, dead roads, and roads erased from every honest map.<br>
<br>
Now she must follow one that crosses the seasons themselves.<br>
<br>
The Season Wound has opened across the Hollow Kingdom, splitting the land into spring, summer, autumn, and winter where they do not belong. Fields freeze before harvest. Snow blooms with flowers. Autumn brings records no office wanted found. Summer burns through roads that should have stayed buried. Every season carries a memory, a debt, and a warning.<br>
<br>
The kingdom is no longer asking to be witnessed.<br>
<br>
It is asking to be held together.<br>
<br>
At the center of it all waits the Crown Chain, an ancient binding tied to dragons, law, roads, bells, and every failed attempt to force the Hollow Kingdom into one obedient shape. Some want to wear it. Some want to break it. Some want to use it before anyone else can.<br>
<br>
Tressa knows what happens when power calls itself necessity.<br>
<br>
Garran Holt stands beside her, scarred by fire, grief, and devotion, still the one man who can steady her when every road beneath her feet changes its mind. Their bond has survived courts, graves, bells, vaults, and the dark between worlds. But love does not spare them from the cost of choice. It only makes the cost matter more.<br>
<br>
With Mara, Voss, Lysa, Branoc, Ysabet, and the witnesses of the First House drawn toward the widening breach, Tressa must face the hardest question the Hollow Kingdom has asked yet:<br>
<br>
How do you mend a kingdom without making yourself its ruler?<br>
<br>
The dragons are watching.<br>
<br>
The seasons are bleeding.<br>
<br>
And the final road to treaty begins at the wound.<br>
<br>
**The Season Wound** is Book Nine of **The Hollow Kingdom**, a dark romantasy series of ancient bells, dangerous roads, dragon-bound law, gothic mystery, fierce witness, sharp-tongued allies, slow-burn devotion, and a kingdom fighting to be remembered without being owned.</p>', '366', 'Dark Romance / Gothic / Romantasy', 'Available', '2026-06-22T04:00:00Z', '9798183799255', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H6CLY8PX', 'https://www.amazon.com/dp/B0H6CLY8PX', '', 0, 1, 1, 1, 0, 0, '31.99', '21.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('66042c5a-e09e-4830-8b7b-f9978f0d0f50', 'Crown of Cinders 3', 'The Crown Owes Blood', 'R.E. Smith', 'Crown of Cinders', '3.0', 'Crownfall was built on furnaces, ledgers, and laws that made cruelty look necessary. When its accord breaks, Sable and the city’s power brokers face the consequences of a system that has always demanded payment in blood.', '<p class="font_8">Crown of Cinders: The Crown Owes Blood is a story about what happens when a city stops pretending it’s civilized.<br>
<br>
Crownfall was built on heat and law—on furnaces, ledgers, and clean words that make dirty things feel necessary. But the accord is broken. The streets are ash-choked. The Office is cutting reality into seams, hunting a single boy they’ve labeled a “hinge”—a living door that can unlock power no one should control. And somewhere under the stone, something older than government has tasted authority…and decided it wants more.<br>
<br>
Queen Sable runs with what’s left: two intact canisters of forbidden glass, a shattered third that birthed fire into open air, a dying knife-man who won’t stop grinning at death, and children learning the hardest lesson a city can teach—how to stay human when everyone wants to file you into property.<br>
<br>
Behind them, Halric and the Synod sell a clean lie to a frightened population. The Tribunal follows orders. The clerk follows procedure. And Old Ash follows hunger.<br>
<br>
Out in the Expanse, there are no walls—only wind, broken iron, and the raw truth of consequences.<br>
<br>
Because a crown isn’t a symbol.<br>
<br>
It’s a debt.<br>
<br>
And this time… **the crown owes blood.**<br>
<br>
**Perfect for readers who want:**<br>
<br>
* dark fantasy with brutal political power games<br>
* relentless momentum, high-stakes pursuit, and hard choices<br>
* adult grit: violence, blood, and moral gray survival<br>
* a “city-as-predator” world where law and fire both have teeth<br>
<br>
**Book Three of the Crown of Cinders series. Best read in order.**</p>', '514', 'Epic / Dark Fantasy / Sword & Sorcery', 'Available', '2026-02-01T05:00:00Z', '9798244083002', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GKXKK5YY', 'https://www.amazon.com/dp/B0GKXKK5YY', '', 0, 1, 1, 1, 0, 0, '20.84', '18.63', '<p>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('672ffebc-7600-41da-b46d-8dadb962fcd2', 'The Vault of Ki: The God Particle', 'The Third Law of Creation', 'R.E. Smith', 'The Vault of Ki', '3.0', 'Years after the events of The Vault of Ki, the world lives among the scars left by fallen gods and alien powers. As governments bargain with forces they barely understand, the question becomes who will write the rules for a world remade by catastrophe.', '<p class="font_8"><strong>When the gods fall, someone has to write the new rules.</strong><br>
Years after the events of <em>The Vault of Ki</em>, the world has learned to live with scars. Vaultborn cities hide beneath ruined ground. Governments negotiate with things they barely understand. And above it all, a shattered alien choir still hums in the dark.<br>
Patricia "Trish" McDuffy was supposed to stay small—a scavenger, a survivor, nobody important. Instead, she walked into a dead government block in old D.C. and found Maia: a sentient system with a war mask welded to her face, a god-engine in her bones, and access to the broken wiring of reality itself.<br>
Together they did the impossible. They took a weaponized belief system designed to sterilize worlds and broke it. The choir is silent. The Loom is cracked. The old “gods” are no longer untouchable.<br>
Now the real work begins.<br>
As Ki becomes the reluctant center of a fragile coalition, Trish, Maia, and the destroyer Nergal find themselves pulled onto a far larger stage. Freed worlds are panicking. Old powers are waking. Valdrathi shards—the former instruments of genocide—are trying to learn the meaning of “I” without a hive to tell them who they are. And the god-particle that once hid in a vault is no longer content to sit still.<br>
Everyone wants new rules. No one agrees on the cost.<br>
From black-site corridors and underground vault-cities to orbiting warships and the first gatherings of a galactic council, <em>The Vault of Ki: Vaultborn – When Broken Gods Need New Rules</em> is a story of survivors who refuse to stay small, and of a universe learning—painfully—how to live without masters.<br>
Perfect for readers who enjoy high-stakes science fiction with mythic echoes, morally grey alliances, and battles fought as much in council chambers as on the battlefield, <em>Vaultborn</em> continues the saga begun in <em>The Vault of Ki</em> and sets the stage for a new kind of cosmic order.</p>', '485', 'Metaphysical & Visionary / Genetic Engineering / Alternate History', 'Available', '2026-02-01T05:00:00Z', '9798278553090', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0CW1NB6CJ', 'https://www.amazon.com/Vault-Ki-Particle-Third-Creation-ebook/dp/B0GB89D1XW?ref_=saga_dp_bnx_dsk_dp', '', 0, 1, 1, 1, 0, 1, '18.7', '11.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p class="font_8">To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('6b8f933a-a684-4bd7-83b9-53304f87d5fc', 'The Empire Prequel 4', 'The Hostage Prince', 'R.E. Smith', 'The Empire Prequel', '4.0', 'The emergency may have ended, but its paperwork and restrictions remain. After the First Chain, permits, protected sites, and technical gatherings become tools of control, as a temporary safety system begins to shape the lives of everyone it was meant to protect.', '<p class="font_8">The Hostage Prince</p>
<p class="font_8"><strong>Book Four of The Empire Prequel</strong></p>
<p class="font_8"><strong>The emergency ended years ago. The paperwork did not.</strong></p>
<p class="font_8">After the First Chain, the old dangers are no longer mysterious enough to ignore.</p>
<p class="font_8">Protected sites have rules.</p>
<p class="font_8">Repair crews need permits.</p>
<p class="font_8">Technical gatherings require notice.</p>
<p class="font_8">Records are kept because someone may need them later.</p>
<p class="font_8">None of that sounds unreasonable.</p>
<p class="font_8">That is exactly the problem.</p>
<p class="font_8">A temporary safety rule becomes a form. The form becomes a copy. The copy becomes a records office. Six months becomes a year, then three. Before long, children know which roads require clay tokens before they understand why the rules exist at all.</p>
<p class="font_8">Naraa remembers when those rules were written.</p>
<p class="font_8">Her son Saran grows up inside them.</p>
<p class="font_8">And a rejected hostage notice bearing his childhood name becomes something the family refuses to throw away.</p>
<p class="font_8">Because governments remember the parts that worked.</p>
<p class="font_8">Families have to remember what the government tried first.</p>
<p class="font_8">Years later, peace between powerful houses depends on another old idea given a cleaner name:</p>
<p class="font_8"><strong>guarantees.</strong></p>
<p class="font_8">Princes, heirs, and relatives travel between courts as living proof that treaties will be honored. Everyone insists they are not hostages.</p>
<p class="font_8">Everyone also understands what happens if the agreement fails.</p>
<p class="font_8">The system is meant to prevent war.</p>
<p class="font_8">Then one of those guarantees dies in custody.</p>
<p class="font_8">Suddenly every safeguard matters.</p>
<p class="font_8">Who chose the physician?</p>
<p class="font_8">Who controlled the road?</p>
<p class="font_8">Who witnessed the treatment?</p>
<p class="font_8">Who pays when a person leaves captivity alive but cannot afford to get home?</p>
<p class="font_8">And what happens to the servant, groom, cook, or attendant when all the laws were written to protect the prince?</p>
<p class="font_8">At the same time, Orun Temür begins tracing changes in wells and springs near the old Wall systems.</p>
<p class="font_8">The evidence is real.</p>
<p class="font_8">The cause is not yet known.</p>
<p class="font_8">He has inherited a world where one badly worded observation can become rumor, policy, suspicion, or accusation before the original record reaches the next city.</p>
<p class="font_8">His father gives him simple advice:</p>
<p class="font_8"><strong>Facts do not love you back. That is why they are useful.</strong></p>
<p class="font_8">The deeper Orun looks, the more uncomfortable the problem becomes. One settlement’s water may depend on a decision that harms another. Complete knowledge could save lives.</p>
<p class="font_8">Complete knowledge in one set of hands could also recreate exactly the kind of power earlier generations tried to prevent.</p>
<p class="font_8"><strong>The Hostage Prince</strong> is Book Four of <em>The Empire Prequel</em>, continuing the six-book story of how temporary safeguards become permanent institutions, how peace creates its own forms of coercion, and how good rules can become more dangerous precisely because they work.</p>
<p class="font_8">For readers who enjoy political epic fantasy, court intrigue, family legacies, legal systems, ancient technology, contested evidence, diplomacy, hostage politics, dry humor, and characters discovering that civilization is often built one reasonable exception at a time.</p>
<p class="font_8"><strong>Nobody wakes up and decides an emergency has become civilization.<br>
They simply copy yesterday’s answer onto tomorrow’s page.</strong></p>', '565', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2027-10-01T04:00:00Z', '9798174966420', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0H5PSZCMP', 'https://www.amazon.com/dp/B0H5PSZCMP', '', 0, 0, 0, 0, 0, 0, '', '', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('6b91ca0c-2451-437c-9e2e-15eff8a267e1', 'The Vault of Ki', 'Origins Were Never Meant to Be Found', 'R.E. Smith', 'The Vault of Ki', '1.0', 'Burned-out investigator Cormac O’Connell accepts one last assignment: auditing a black-site vault beneath a government facility. Inside, he encounters Maia, a sentient system with alarming access, and an impossible ancient machine that could change humanity’s understanding of its own past.', '<p class="font_8">Cormac O’Connell is done chasing ghosts for other people’s secrets. Burned-out and half-broken, he takes one last quiet assignment: audit an aging black-site vault buried under a government facility that should have been decommissioned years ago.<br>
Inside, nothing is quiet.<br>
The vault houses Maia—a sentient system with too much personality and far too much access—and an artifact that should not exist: a machine older than human history, built by the ones our ancestors called gods.<br>
The Anunnaki didn’t just visit. They archived.<br>
When a signal from “Vault Zero” reappears—a site that every record insists was sealed in 1985—Maia starts pulling threads. A pattern emerges in the human genome: seventy-two marked souls, living descendants of an ancient project called Adamu. One of them is an eleven-year-old girl in a forgotten refugee camp who hums songs from twelve thousand years ago.<br>
As Cormac digs, the story behind humanity begins to fracture. The gods were engineers. Their angels revolted. Vaults were not tombs, but backups. And history isn’t a straight line—it’s a loop, grinding toward overwrite.<br>
If he opens what was meant to stay buried, the world may not survive the truth that comes out.<br>
If he doesn’t, the recursion will finish without him.<br>
Either way, something is waking up beneath our idea of “human.”<br>
Perfect for readers of Blake Crouch and Michael Crichton, and for anyone who ever watched Stargate and wondered what would really happen if the gods came back for their data.<br>
The Vault of Ki: Origins Were Never Meant to Be Found is the first novel in a saga of ancient engineers, stubborn humans, and the one thing that refuses to be deleted: memory.</p>', '565', 'Metaphysical & Visionary / Genetic Engineering / Alternate History', 'Available', '2025-12-02T05:00:00Z', '9798277094310', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0CW1NB6CJ', 'https://www.amazon.com/dp/B0CW1NB6CJ', '', 0, 1, 1, 1, 0, 0, '19.1', '17.49', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('6d57b603-51e2-49b1-b591-c43a3963cac1', 'The Dead Remember', 'Blood, Memory & Desire', 'R.E. Smith', 'The Empire Prequel', '', 'Mara Vey prepares the dead for burial while hiding a dangerous gift: she can sometimes experience what the dead remember through blood, bone, and objects connected to violent deaths. When Lady Selene Arat is declared a suicide, Mara recognizes murder and must uncover the truth.', '<p class="font_8">The dead remember. But memory lies.<br>
<br>
Mara Vey has spent her life preparing the dead for burial and hiding the one thing that could get her killed: when she touches blood, bone, or the objects left behind by violent death, she can sometimes remember what the dead remember.<br>
<br>
Then Lady Selene Arat arrives at the House of Silence.<br>
<br>
Her death has been declared a suicide. Mara knows it is murder.<br>
<br>
And in Selene’s final fractured memory, Mara sees three impossible things: a black sun, the face of Commander Cassian Rhor, and Selene herself looking through death to whisper Mara’s name.<br>
<br>
Cassian is dangerous, controlled, and far too familiar with secrets Mara was taught never to reveal. He may be connected to Selene’s murder. He may also be the only person capable of keeping Mara alive long enough to uncover the truth.<br>
<br>
Their investigation leads beneath the golden city of Sareth, into a conspiracy older than the kingdom’s official history and toward the forbidden Archive of Echoes, where generations of stolen memories have been hidden from the living.<br>
<br>
Kings have killed to keep it closed.<br>
<br>
Others are willing to burn a city to open it.<br>
<br>
And somehow, the key has been buried inside Mara since childhood.<br>
<br>
As attraction turns to trust and trust becomes far more dangerous than desire, Mara must decide whether the truth belongs to those powerful enough to control it, those wounded enough to demand it…<br>
<br>
or to no one at all.<br>
<br>
THE DEAD REMEMBER is a dark romantic fantasy and supernatural mystery filled with forbidden memory magic, ancient conspiracies, morally complicated characters, murder, betrayal, slow-burning desire, and a romance where trust may be more dangerous than death.</p>', '478', 'Dark Fantasy / Romantic / Paranormal', 'Available', '2026-10-04T04:00:00Z', '9798178902257', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0HLYHZCKV', 'https://www.amazon.com/dp/B0HLYHZCKV', 'https://play.google.com/store/audiobooks/details?id=AQAAAECGbwEvlM', 0, 1, 1, 1, 0, 0, '27.0', '17.0', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('6e786dbf-c55c-48ef-afc2-dd65f550c035', 'My Legacy', 'From Conquest to Cradle, From Ashes to Hope, Fourteen Generations Across the Waters of Time', 'R.E. Smith', '', '', 'Tracing one Rhode Island family across four centuries, My Legacy follows the Smiths from Roger Williams’s exile in 1635 through mill towns and modern America. This family history honors generations of millers, soldiers, farmers, builders, mothers, teachers, and dreamers.', '<p class="font_8"><em>My Legacy</em> is a journey through four centuries of one Rhode Island family whose roots reach back to the very founding of the colony itself. From the exile of Roger Williams in 1635 to the mill towns of Manville and the quiet streets of modern America, this book follows the steady, unbroken line of the Smiths—millers, soldiers, farmers, builders, mothers, teachers, and dreamers.</p>
<p class="font_8">Told with the tenderness of memory and the grit of lived experience, the story begins in a house filled with generations, where a young boy asks his grandfather what their nationality is and receives an answer that will shape his entire understanding of identity: <em>We’re Rhode Islanders.</em> From that moment forward, the past becomes a calling.</p>
<p class="font_8">Through richly woven narrative, ancestral records, imagined-but-true vignettes, and reverent portraits of men and women long gone, <em>My Legacy</em> traces the Smith family from 1600s Providence through war, migration, industry, and change. Each chapter reveals the people behind the names—Warren the blacksmith-poet, Hattie the lantern of the home, Nicholas the wheelwright, Angeline the teacher, Edward the quiet patriot, Kenneth the soldier who came home and built peace, and the modern descendants who carry that light forward.</p>
<p class="font_8">What emerges is not just genealogy, but a living testament to resilience, belonging, and the sacred weight of family. The book closes in the present day, where grandchildren run beneath Florida pines carrying the same fire that once warmed colonial hearths, mill floors, and frontier cabins.</p>
<p class="font_8">Part history, part memoir, part love letter to blood and soil, <em>My Legacy</em> is a tribute to the people who built a family strong enough to withstand centuries—and tender enough to remain unforgettable.</p>
<p class="font_8"><em>In these pages, the past is not gone. It is alive, speaking through the voices of those who lived, loved, fought, worked, and handed their stories forward. This is the Smith lineage—rooted, weathered, and unbreakable.</em></p>', '137', 'Nonfiction / Family History / Memoir', 'Available', '2026-01-01T05:00:00Z', '979-8274437363', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0G2TD647Y', 'https://www.amazon.com/dp/B0G2TD647Y', '', 0, 1, 1, 1, 0, 0, '14.12', '10.89', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('71b3b202-ce43-4acf-9e80-52f3676fa831', 'Wolves of Tiber 2', 'Oathbound Thrones', 'R.E. Smith', 'Wolves of Tiber', '2.0', 'A king’s death has not quieted Rome. Survivors of the purges regroup, purity preachers target the Bloodborn, and stone-winged allies watch from the rooftops as the city’s new order struggles to control the forces it unleashed.', '<p class="font_8">A king is dead. The city should be quiet.<br>
It isn’t.<br>
The rope may have ended the old reign, but Rome doesn’t change its appetite—it only changes who it feeds on. In the streets, the leftovers of the purges gather in hidden nests. In the temples, purity men whisper that the Bloodborn are an abomination. On the rooftops, stone-winged allies keep their bargains… and watch for the moment they’re no longer worth keeping.<br>
<strong>Aurelio</strong> tries to turn victory into law. He needs order, courts, gates, and a future the people can live inside.<br>
<strong>Remo</strong> wants justice the old way—fast, personal, and final.<br>
Between them, <strong>Cassia</strong> navigates the knives of council rooms and alleyways, hunting threats that don’t wear crowns. And from the ruin belt, <strong>Nera</strong> listens to the city like it’s a heartbeat—waiting to see which brother becomes Rome’s shield… and which becomes its plague.<br>
Because the real war isn’t over.<br>
It has simply moved underground.<br>
And every throne in Rome is built on an oath that can be broken.</p>', '448', 'Genre Fiction / Horror / Dark Fantasy / Epic / Historical', 'Available', '2026-01-01T05:00:00Z', '9798279244256', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GB2WWN5R', 'https://www.amazon.com/dp/B0GB2WWN5R', '', 0, 1, 1, 1, 0, 0, '20.34', '12.59', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('73d6e539-041f-4a63-b763-fe69a6389f0d', 'Chimney Hill', 'Beneath Cold Hill', 'R.E. Smith', '', '', 'Daniel and Rachel Harker leave Rochester for a fresh start in rural Kentucky, hoping to build a home, serve their church, and raise a family. But the land remembers its past, and the well at Chimney Hill is not merely dry: it is thirsty.', '<p class="font_8"><strong>Chimney Hill</strong><br>
<em>By R. E. Smith</em><br>
<strong>"The land remembers. The well is not dry—but thirsty."</strong></p>
<p class="font_8">Daniel and Rachel Harker are young, in love, and chasing a dream of simple living in the Appalachian mountains. When they leave behind the cold concrete of Rochester, New York, for a remote patch of land in rural Kentucky, they’re looking for a fresh start—a home to build, a church to serve, a family to grow.</p>
<p class="font_8">But what they find instead is <em>Chimney Hill</em>—a moss-covered relic of a preacher’s house long since burned, with only the chimney and rumors left behind. Beneath the soil sleeps an ancient hunger. Locals won’t speak of it. Maps warn against digging. The old woman at the general store whispers of Sylas Thorne—the blind preacher who baptized in tar and spoke in tongues that turned men mad.</p>
<p class="font_8">As Rachel''s dreams fill with spirals and songs in lost languages, and Daniel finds secrets carved beneath the very foundation of their land, the couple is drawn into a haunting they can’t explain—and a truth they may not survive.</p>
<p class="font_8">Rooted in Appalachian folklore and simmering with dread, <em>Chimney Hill</em> is a slow-burn folk horror novel about faith, memory, and the cost of building a future on cursed ground.</p>', '120', 'Folklore / 21st Century / Mythology', 'Available', '2025-08-01T04:00:00Z', '9798275423723', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0FKVKZQ1Z', 'https://www.amazon.com/dp/B0FKVKZQ1Z', 'https://play.google.com/store/audiobooks/details?id=AQAAAEBGUAkQXM', 0, 1, 1, 1, 0, 0, '14.64', '9.33', '<p>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('746d77a9-7785-45f6-a0b3-87ce133107d5', 'The Ghost of Chipola', 'Debt Crossing', 'R.E. Smith', 'The Vault of Ki', '', 'In early-1800s Marianna, Florida, a new bridge promises progress until an old moonshiner is murdered and his ghost refuses to leave. Unable to act directly, the dead man haunts the living, stirring trouble in a town already divided by ambition and change.', '<p class="font_8">In the backwoods of early-1800s Marianna, Florida, a new crossing over the Chipola River is supposed to mean progress—shorter rides, fuller markets, a town finally stepping out of the mud.</p>
<p class="font_8">Then an old moonshiner is murdered the day after the bridge opens.</p>
<p class="font_8">And the dead man doesn’t leave.</p>
<p class="font_8">He can’t lift a hand or swing a blade—so he does what spiteful ghosts do best: he <em>haunts</em>. He appears in the wrong place at the wrong time, whispers into the dark, spooks horses, bends crowds, and turns ordinary fear into deadly motion. One death becomes another. A headless driver. A hunter thrown hard. A town slowly learning that the bridge doesn’t just carry people across water—it carries <em>debt</em>.</p>
<p class="font_8">Sheriff Caleb Rutledge tries to hold the line with law and grit, but Marianna has other leaders with louder voices. Reverend Pike sells salvation by lantern light. Hollis Tarrant sells “protection” with strings attached. And the townsfolk—hungry for a story that makes them feel safe—start treating fear like a ritual.</p>
<p class="font_8">At the center of it all is Elizabeth Jane Bellamy, a bride caught between love, gossip, and a town that keeps asking her to prove she belongs. When shame and superstition push her into the night with a lantern in hand, the crossing finally takes what it’s been waiting for…</p>
<p class="font_8">…and earns the name that will follow it into legend.</p>
<p class="font_8"><strong>The Ghost of Chipola: Debt Crossing</strong> is a Southern gothic horror novel of curses, crowds, and the terrible truth that the dead don’t always need to touch you to kill you—sometimes they only need to make you take one wrong step.</p>
<p class="font_8"><em>Some bridges don’t just connect two shores. They collect.</em></p>', '533', 'Horror / Southern Gothic', 'Available', '2025-12-22T05:00:00Z', '9798279423125', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GBXX1N7G', 'https://www.amazon.com/dp/B0GBXX1N7G', '', 1, 1, 1, 1, 0, 0, '19.34', '11.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('789ad258-78dd-4dd8-9b37-43a8028a30fb', 'No Disappearing', 'A Second-Chance', 'R.E. Smith', '', '', 'Mara rebuilt her life after leaving a love that was consuming them both. When the person she tried to leave behind returns, she must decide whether a second chance can be different, or whether old patterns will pull them back into the same hurt.', '<p class="font_8">No Disappearing: A Second-Chance is a love story about what happens after the big goodbye—when the person you swore you were done with shows up again, looking familiar… and dangerous in the quiet way.<br>
<br>
Mara didn’t leave because she stopped loving him. She left because love wasn’t enough to keep two people from burning each other down. She rebuilt her life the old-fashioned way: one day at a time, one hard boundary at a time, one “I’m fine” at a time—until “fine” almost started to feel real.<br>
<br>
Then he comes back.<br>
<br>
Not with grand speeches or movie apologies. With the kind of presence that makes the room tilt. With unfinished sentences, old jokes that still land, and the same gravity that once pulled her under. The past starts breathing again—through friends who remember too much, family who wants answers, and a town that watches like it’s free theater.<br>
<br>
Because this isn’t just about whether they still want each other.<br>
<br>
It’s about whether they can face what broke them without using it as a weapon. Whether the truth can finally be said out loud. Whether two people can learn a new way to love—without disappearing when it gets hard.<br>
<br>
Tense, tender, and uncomfortably honest, No Disappearing is a second-chance romance for readers who like their chemistry sharp, their emotions earned, and their happily-ever-after fought for.<br>
<br>
Perfect for fans of:<br>
<br>
second-chance romance<br>
<br>
forced proximity / stuck together vibes<br>
<br>
sharp dialogue + slow-burn heat<br>
<br>
messy history, real healing, real payoff<br>
<br>
Sometimes the bravest thing isn’t coming back.<br>
It’s staying.</p>', '553', 'Romance / Second-Chance Romance', 'Available', '2026-01-01T05:00:00Z', '9798242117310', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GDKZ29HC', 'https://www.amazon.com/dp/B0GDKZ29HC', '', 0, 1, 1, 1, 0, 0, '19.68', '11.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('78e6c113-eb66-4230-9e26-f1fc07e47e4d', 'Timeless Love', 'The Wrath', 'R.E. Smith', '', '', 'Long before Harrow House became a grand hotel, the land held grief, blood, and an ancient oak that remembered. When surveyors uncover something in the storm-soaked woods, they awaken the wrath of a man who died protecting the woman he loved.', 'Some love stories end in death. Some refuse to end at all. Long before Harrow House became a grand hotel, the land belonged to blood, fire, grief, and an ancient oak that remembered everything. In 1880, surveyors stumble upon something buried in the storm-soaked woods near the Atlantic coast. What they awaken is the wrath of a man who died protecting the woman he loved and the child they would never hold. Years later, Harrow House rises over that same ground, but beneath its beauty something waits. When Rene and her son Daren are drawn into the secrets of Harrow House, they uncover a haunting born not from evil, but from love twisted by grief. Timeless Love: The Wrath is a supernatural horror novel about grief, family, vengeance, and the terrifying power of love when death cannot silence it.', '389', 'Horror / Supernatural', 'Available', '2026-06-01T04:00:00Z', '9798199488754', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GX2TM2RY', 'https://www.amazon.com/dp/B0GX2TM2RY', '', 0, 1, 1, 1, 0, 0, '18.78', '11.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('8062635f-0ebf-4e4e-9a99-5728068662b6', 'The Vault of Ki: Vaultborn', 'When Broken Gods Need New Rules', 'R.E. Smith', 'The Vault of Ki', '2.0', 'Years after the fall of the old order, Vaultborn cities hide beneath ruined ground and governments negotiate with powers they barely understand. Patricia “Trish” McDuffy, a scavenger determined to survive unnoticed, is drawn into a struggle over who gets to define the rules of a changed world.', '<p class="font_8"><strong>When the gods fall, someone has to write the new rules.</strong><br>
Years after the events of <em>The Vault of Ki</em>, the world has learned to live with scars. Vaultborn cities hide beneath ruined ground. Governments negotiate with things they barely understand. And above it all, a shattered alien choir still hums in the dark.<br>
Patricia "Trish" McDuffy was supposed to stay small—a scavenger, a survivor, nobody important. Instead, she walked into a dead government block in old D.C. and found Maia: a sentient system with a war mask welded to her face, a god-engine in her bones, and access to the broken wiring of reality itself.<br>
Together they did the impossible. They took a weaponized belief system designed to sterilize worlds and broke it. The choir is silent. The Loom is cracked. The old “gods” are no longer untouchable.<br>
Now the real work begins.<br>
As Ki becomes the reluctant center of a fragile coalition, Trish, Maia, and the destroyer Nergal find themselves pulled onto a far larger stage. Freed worlds are panicking. Old powers are waking. Valdrathi shards—the former instruments of genocide—are trying to learn the meaning of “I” without a hive to tell them who they are. And the god-particle that once hid in a vault is no longer content to sit still.<br>
Everyone wants new rules. No one agrees on the cost.<br>
From black-site corridors and underground vault-cities to orbiting warships and the first gatherings of a galactic council, <em>The Vault of Ki: Vaultborn – When Broken Gods Need New Rules</em> is a story of survivors who refuse to stay small, and of a universe learning—painfully—how to live without masters.<br>
Perfect for readers who enjoy high-stakes science fiction with mythic echoes, morally grey alliances, and battles fought as much in council chambers as on the battlefield, <em>Vaultborn</em> continues the saga begun in <em>The Vault of Ki</em> and sets the stage for a new kind of cosmic order.</p>', '578', 'Metaphysical & Visionary / Genetic Engineering / Alternate History', 'Available', '2026-02-01T05:00:00Z', '9798278550624', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0CW1NB6CJ', 'https://www.amazon.com/Vault-Ki-Vaultborn-Broken-Rules-ebook/dp/B0G5N33KVN?ref_=saga_dp_bnx_dsk_dp', '', 0, 1, 1, 1, 0, 1, '21.82', '14.07', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p class="font_8">To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('81c88659-24f6-43bf-a491-2b3260d2535f', 'The Hollow Kingdom 1', 'The Empty Throne', 'R.E. Smith', 'The Hollow Kingdom', '1.0', 'Crown Works surveyor Tressa Vale knows roads should not change their own length, yet the road to Bellharrow has added seven miles overnight. Her investigation leads to a bell that should not ring, an impossible throne, and a kingdom built on secrets buried beneath its laws.', '<p class="font_8">**A road that should not exist. A bell that should not ring. A throne no one living should claim.**<br>
Tressa Vale knows roads.<br>
As a Crown Works surveyor, she has measured the kingdom’s boundaries in rain, frost, mud, and miserable company. Roads may sink, flood, crack, or take offense at being trusted, but they do not add seven miles to themselves overnight.<br>
The road to Bellharrow has done exactly that.<br>
When Tressa follows the impossible distance into the village, she finds a church hiding old fear, a bell waking under stone, and a buried law the Crown tried to forget. Bellharrow is not just a place on a map. It is a doorway into something older, darker, and far more dangerous.<br>
Then Garran Holt arrives.<br>
Holt is a Warden, a man sent where old things go wrong and people are grateful if he leaves them alive. He is dangerous, controlled, and far too hard to ignore. Tressa needs his strength. Holt needs her measure. Neither of them trusts the pull between them, and neither has time to pretend it is not there.<br>
Because the Hollow Kingdom is waking.<br>
Old roads are opening. Old claims are answering. A claimant with a polished smile wants what should stay buried. And somewhere beneath Crownmark waits an empty throne tied to bells, blood, law, and the kind of power that turns ambition into ruin.<br>
Tressa was sent to measure a road.<br>
Now she must decide which kingdom gets to live.<br>
**The Empty Throne** is Book One of **The Hollow Kingdom**, a dark romantasy series filled with dangerous roads, ancient bells, buried law, slow-burn tension, gothic mystery, and a romance forged in fire, witness, and impossible choices.</p>', '533', 'Dark Romance / Gothic / Romantasy', 'Available', '2026-06-22T04:00:00Z', '9798183669503', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H6CKR376', 'https://www.amazon.com/dp/B0H6CKR376', '', 0, 1, 1, 1, 0, 0, '31.99', '21.99', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('8609e26f-f0da-4acb-b92c-294b17c08c42', 'The Woods', '', 'R.E. Smith', '', '', 'In Briar Falls, everyone knows the version of themselves they work hardest to protect. When Gary Carter falls into a hidden pit while searching for his dog, an impossible voice offers him a bargain: someone else can suffer in his place. The choice spreads consequences through the town.', '<p class="font_8">Briar Falls is the kind of town where everyone knows your name, your business, and the version of yourself you work hardest to protect. At the edge of town stand the woods, patient, silent, and waiting. When Gary Carter falls into a hidden pit while searching for his dog, he hears an impossible voice and is offered a bargain: someone else can suffer in his place. What begins as one desperate act spreads through Briar Falls. The townspeople discover that pain can be passed on, suffering can be traded, and the woods are always listening. Led by Lena Cross, a group begins to suspect the woods are choosing, trading, and demanding balance. The Woods is a slow-burn supernatural horror novel about fear, guilt, survival, and the terrible bargains people make when they believe they have no other choice.</p>', '253', 'Horror / Supernatural', 'Available', '2026-05-25T04:00:00Z', '9798198504196', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H24C82M7', 'https://www.amazon.com/dp/B0H24C82M7', '', 1, 1, 1, 1, 0, 1, '16.44', '10.95', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('87b174cd-ac48-495c-8110-5000c46fc8ba', 'THE OLD MAN''S FIDDLE', 'The Life and Stories of Owen Dixon', 'R.E. Smith', '', '', 'Thirteen-year-old Edward loses his way in the winter woods of Rhode Island and finds Owen Dixon, an old man nearly forgotten by the world. Through Owen’s extraordinary life and his fiddle, Edward discovers a story whose memory will carry across generations.', '<p class="font_8"><strong>THE OLD MAN''S FIDDLE</strong><br>
<em>The Life and Stories of Owen Dixon</em><br>
A boy lost in the winter woods. An old man the world had nearly forgotten. And a fiddle that would carry his memory for generations.<br>
Thirteen-year-old Edward never intended to find Owen Dixon.<br>
But deep in the winter woods of Rhode Island, a wrong turn leads him to a remote cabin and an old man whose life seems almost too remarkable to be true.<br>
Owen has been a wanderer, trapper, jailbird, circus man, storyteller, and fiddler. He has known hardship, trouble, laughter, and the restless America of the nineteenth century. To most people, he is simply an eccentric old man living out his remaining years beyond the edge of town.<br>
To Edward, he becomes something more.<br>
A grandfather.<br>
A teacher.<br>
A keeper of stories.<br>
As the unlikely bond between the old man and the boy grows, Owen begins passing down the pieces of a life that might otherwise disappear. And eventually, he entrusts Edward with something more enduring than any story:<br>
his fiddle.<br>
Inspired by the documented life of Owen Dixon (1824–1906) and generations of family history, The Old Man’s Fiddle weaves historical record, family tradition, and imagined moments into an intimate story about memory, inheritance, and the quiet ways ordinary people survive the passage of time.<br>
Because perhaps a man really does die twice: once when his life ends, and again when no one remembers his name.<br>
More than a century later, Owen Dixon is remembered.<br>
And somewhere, the music is still playing.</p>', '225', 'General / 19th Century / Coming of Age', 'Available', '2026-10-05T04:00:00Z', '9798177509280', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0HM2716MJ', 'https://www.amazon.com/dp/B0HM2716MJ', 'https://play.google.com/store/audiobooks/details/R_E_Smith_THE_OLD_MAN_S_FIDDLE?id=AQAAAECGv1H_xM', 1, 1, 1, 1, 1, 0, '17.0', '12.0', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('902f0bff-eae5-445e-8144-5f29443d3f5e', 'The Valley', 'Bjorn and the Norsemen', 'R.E. Smith', '', '', 'Bjorn’s people cross harsh country seeking safety, land, and a future free from Roman chains. But when the mountains open into a valley that feels unnaturally quiet, the struggle for survival becomes a test of whether peace can endure in a world shaped by war.', '<p class="font_8">The Valley: Bjorn and the Norsemen is not a tale told by firelight. It’s a march. A hunger. A storm with teeth.<br>
<br>
Bjorn’s people have crossed leagues of hard country chasing safety, land, and the kind of future that doesn’t come with Roman chains. But the world doesn’t hand out peace. It tests it. And when the mountains open into a valley that feels too quiet—too certain—Bjorn learns the oldest truth of war:<br>
<br>
Some places don’t want you there.<br>
<br>
The valley is beautiful in the way a blade is beautiful. It watches. It waits. It takes measurements. Every step forward costs more than the last—food, strength, blood, faith. Men who have survived sea raids and winter crossings begin to crack under something they can’t name. The storm that rolls down from the heights isn’t just weather. It’s a judgment.<br>
<br>
And Rome is never far.<br>
<br>
As danger tightens, Bjorn must hold his people together with more than steel. He must make choices that stain. He must decide what kind of leader he is when courage stops being a speech and becomes a debt paid in the dark. The Norse don’t pray for mercy. They build their own. But the valley has its own laws—and it collects.<br>
<br>
Gritty, brutal, and fiercely human, The Valley: Bjorn and the Norsemen is a historical saga of survival, loyalty, and the cost of pushing into lands that do not forgive.<br>
<br>
If you love hard-edged historical fiction, war bands, Roman shadows, and stories where the wilderness is as dangerous as any army… step into the valley.<br>
<br>
Just don’t expect it to let you leave clean.</p>', '324', 'Fiction / Historical / Medieval', 'Available', '2026-01-01T05:00:00Z', '9798242119918', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/Valley-Bjorn-Norsemen-R-Smith-ebook/dp/B0GDM4VCNL?ref_=ast_author_dp_rw&th=1&psc=1&dib=eyJ2IjoiMSJ9.m6xfLpmN5JIc8V6rwFPJEV4RiQHPba-hPy-hyweQWG24Wf37PIfdnXiv82JeglR9VDgfHiLVwqQSu5VXrGhjOF5f2JTl15xz2YPgxv1ryvY8NGeHIcDlfXzvLxB9GUi5AXwyuoXg4hVIf0xdYNSr9-0ZwR_WFqSb5KDH6ZaJmK4VMigUgm1sAYVwVpHNLC4d5_gS_l1m4WtpXjR-juU2DUqySobcncDdGrhZDh2QLT4.IJsfZ1WN5iFrREAISw4QRMQgGb886lX0t9NYH_Ywq98&dib_tag=AUTHOR', 'https://www.amazon.com/Valley-Bjorn-Norsemen-R-Smith-ebook/dp/B0GDM4VCNL?ref_=ast_author_dp_rw&th=1&psc=1&dib=eyJ2IjoiMSJ9.m6xfLpmN5JIc8V6rwFPJEV4RiQHPba-hPy-hyweQWG24Wf37PIfdnXiv82JeglR9VDgfHiLVwqQSu5VXrGhjOF5f2JTl15xz2YPgxv1ryvY8NGeHIcDlfXzvLxB9GUi5AXwyuoXg4hVIf0xdYNSr9-0ZwR_WFqSb5KDH6ZaJmK4VMigUgm1sAYVwVpHNLC4d5_gS_l1m4WtpXjR-juU2DUqySobcncDdGrhZDh2QLT4.IJsfZ1WN5iFrREAISw4QRMQgGb886lX0t9NYH_Ywq98&dib_tag=AUTHOR', '', 0, 1, 1, 0, 0, 1, '16.88', '10.88', '<p class="font_8"><u>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</u></p>', 'resmithauthor@gmail.com', '<p class="font_8">To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('90c558a1-58e8-435d-818d-a4808a4e7ffa', 'Crowns of Blood 1', 'Kethria in Flames', 'R.E. Smith', 'Crowns of Blood', '1.0', 'Kethria, the Crownlands’ iron-rich jewel, was built to outlast kings. Now the great city discovers that its walls and foundries cannot protect it from a world turning hostile, as the first flames threaten to destroy the order on which its power rests.', '<p class="font_8">Kethria was built to outlast kings.</p>
<p class="font_8">It won’t.</p>
<p class="font_8"><strong>CROWNS OF BLOOD: KETHRIA IN FLAMES</strong> is a brutal, cinematic plunge into the moment a great city realizes the world has teeth—and it’s biting down.</p>
<p class="font_8">Kethria is the Crownlands’ jewel: iron foundries roaring night and day, river trade fat with coin, stone walls that have laughed at siege engines for generations. Inside those walls, power moves the way smoke does—quiet, constant, everywhere. Lords bargain in candlelit chambers. Guilds count favors like they’re prayers. Soldiers hold the line for rulers who don’t know their names. Common folk keep their heads down and their families fed.</p>
<p class="font_8">And then the sky shifts.</p>
<p class="font_8">When fire comes, it doesn’t arrive politely. It tears open the old order and drags the truth into the streets: the Crown is weaker than it looks, loyalty is rented, and “safety” is just a story people tell themselves so they can sleep.</p>
<p class="font_8">In the inferno, choices get simple in the worst way:</p>
<ul class="font_8">
  <li><p class="font_8"><strong>Hold the gate</strong> and die honest.</p></li>
  <li><p class="font_8"><strong>Run the alleys</strong> and live hunted.</p></li>
  <li><p class="font_8"><strong>Stand with the Crown</strong> and become the villain someone needs.</p></li>
  <li><p class="font_8"><strong>Turn on it</strong> and discover you’re not the only one with a knife.</p></li>
</ul>
<p class="font_8">This is a book about the <strong>first scream</strong> of a long war—the one history always edits into a cleaner sentence. It’s about oaths snapping under pressure, about the cost of command, about the ugly math of survival when monsters aren’t myths anymore and the city’s own heart starts beating against it.</p>
<p class="font_8">Expect:<br>
<strong>Dark, grounded epic fantasy</strong> with war-level intensity<br>
<strong>Political intrigue</strong> where every alliance has a hidden blade<br>
<strong>Siege fire and street violence</strong> that feels close enough to smell<br>
<strong>Hard choices</strong> where “right” and “alive” stop being the same thing<br>
A world that rewards <strong>ruthlessness, strategy, and nerve</strong></p>
<p class="font_8">If you like your fantasy with <strong>Game of Thrones–style stakes</strong>, <strong>battlefield urgency</strong>, and characters who earn every inch they keep breathing, <strong>KETHRIA IN FLAMES</strong> will grab you by the throat and drag you through the smoke.</p>
<p class="font_8">Because Kethria doesn’t fall all at once.</p>
<p class="font_8">It falls <strong>person by person</strong>—one betrayal, one broken oath, one burning tower at a time.</p>
<p class="font_8"><strong>Begin the prequel saga to Crown of Cinders.</strong><br>
<strong>CROWNS OF BLOOD: KETHRIA IN FLAMES</strong><br>
By <strong>R. E. Smith</strong></p>', '525', 'Epic / Dark Fantasy / Sword & Sorcery', 'Available', '2026-02-01T05:00:00Z', '9798245714714', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0GKXLBR3H', 'https://www.amazon.com/dp/B0GKXLBR3H', '', 0, 1, 1, 1, 0, 0, '18.88', '11.99', '<p>To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('98b1a665-7614-4752-9e3c-8dc0c24bdc4f', 'The Empire 3', 'Black Dawn', 'R.E. Smith', 'The Empire', '3.0', 'The old Empire is dead, but its laws endure. Beneath the Black Sand Sea, an awakened city offers food, water, protection, and order through ancient systems that still judge bloodlines, debts, and social roles, forcing the living to confront a past that never truly disappeared.', '<p class="font_8">Black Dawn</p>
<p class="font_8"><strong>Book Three of The Empire</strong></p>
<p class="font_8"><strong>The old empire is dead. Its laws are not.</strong></p>
<p class="font_8">Beneath the Black Sand Sea, a buried city has awakened.</p>
<p class="font_8">Its roads still function. Its gates still judge. Its archives remember bloodlines, debts, offices, armies, slaves, rulers, and crimes committed centuries before the living were born. It offers food, water, protection, and order.</p>
<p class="font_8">It also believes every person belongs somewhere.</p>
<p class="font_8">And to someone.</p>
<p class="font_8">Roxana Vardan enters the city hoping to recover missing workers and prevent her father from claiming its ancient power. Instead, she discovers a civilization capable of turning contracts into chains and freedom into an administrative error. Mara and the trapped laborers begin fighting the system from inside, forcing it to confront something its builders never truly understood: <strong>consent</strong>.</p>
<p class="font_8">Across the continent, the consequences spread.</p>
<p class="font_8">Shirin challenges the Vardan empire her father built from debt and inheritance. Lan Su discovers that the River Kingdom has buried the wrong king. Xu finds himself offered something every emperor dreams of: the power to impose justice everywhere at once. Arslan is offered control over the ancient forges, gates, weapons, and dragons.</p>
<p class="font_8">Every offer comes with the same poison hidden beneath it.</p>
<p class="font_8">Obedience first. Freedom later.</p>
<p class="font_8">The buried system does not merely want rulers.</p>
<p class="font_8">It wants agreement.</p>
<p class="font_8">It counts movement as consent. Death as participation. Blood as authority. Hunger as leverage. It can rebuild roads overnight, feed starving children, restore lost cities, and command armies without ever believing itself cruel.</p>
<p class="font_8">As ancient beacons ignite and forgotten armies begin to rise, enemies who once fought one another must somehow build an alliance without creating another empire in the process.</p>
<p class="font_8">No single ruler can command it.</p>
<p class="font_8">No single army can save it.</p>
<p class="font_8">And when the black sun rises over Red Gate, the choice becomes brutally simple:</p>
<p class="font_8"><strong>Accept perfect order...</strong></p>
<p class="font_8"><strong>or defend the dangerous right to choose wrong.</strong></p>
<p class="font_8"><em>Black Dawn</em> is Book Three of <strong>The Empire</strong>, a completed nine-book adult epic fantasy series of war, political intrigue, ancient technology, dragons, rebellion, love, loyalty, slavery, freedom, and the terrible price of power exercised for someone else’s own good.</p>
<p class="font_8"><strong>The dawn is black because the sun has returned.<br>
And this time, it remembers everyone.</strong></p>', '434', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2026-12-01T05:00:00Z', '9798170037872', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0HJWX17FV', 'https://www.amazon.com/dp/B0HJWX17FV', '', 0, 0, 0, 0, 0, 0, '32.0', '17.0', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('99d934d2-eacf-41f1-b293-714837bfb935', 'The Empire 6', 'Blood Charter', 'R.E. Smith', 'The Empire', '6.0', 'Three months after Arslan’s assassination, the north faces a crisis no sword can solve. Qulan commands the strongest lawful military force, Tura refuses to inherit authority through love, and Khasar carries Arslan’s legacy as the new order struggles to determine who has the right to rule.', '<p class="font_8">Blood Charter</p>
<p class="font_8"><strong>Book Six of The Empire</strong></p>
<p class="font_8"><strong>They forbade inheritance. Then the armies asked who would sign the next order.</strong></p>
<p class="font_8">Arslan is dead.</p>
<p class="font_8">The laws he helped build are still alive.</p>
<p class="font_8">Three months after his assassination, the north faces a crisis no sword can solve. Qulan commands the strongest lawful military force, but she has no automatic civil mandate. Tura refuses to inherit authority through love. Khasar carries Arslan’s name, grief, and enormous symbolic weight, but no crown, office, or command.</p>
<p class="font_8">That was the point.</p>
<p class="font_8">Now everyone has to live with it.</p>
<p class="font_8">Road councils need contracts signed. Soldiers need lawful orders. Widows need payments. Camps demand representation. Merchants need guarantees that will survive the next election. Armed institutions cannot simply stop functioning while frightened people debate legitimacy.</p>
<p class="font_8">And frightened people have begun asking whether blood might be easier.</p>
<p class="font_8">Across the north, factions gather around competing answers. Some want fixed civilian authority. Others want rotating councils, stronger military continuity, or a ceremonial role for Khasar that they insist carries no real power. Every proposal claims to preserve freedom.</p>
<p class="font_8">Every proposal creates someone who can sign.</p>
<p class="font_8">Then Xu is badly injured.</p>
<p class="font_8">For the first time, the Office of Maritime Provision must function without the young emperor who helped build and restrain it. Mei Ren is offered the simplest solution: rule through household, marriage, and motherhood.</p>
<p class="font_8">She refuses.</p>
<p class="font_8">The Office continues anyway.</p>
<p class="font_8">That may be more dangerous than failure.</p>
<p class="font_8">As rival orders move soldiers before truth can catch them, custody becomes politics, roads become borders, river gates become weapons, and delegates attempting to write a new charter discover that every clause eventually reaches a body.</p>
<p class="font_8">Who may close a road?</p>
<p class="font_8">Who can raise troops?</p>
<p class="font_8">Who controls a child surrounded by armed adults claiming to protect him?</p>
<p class="font_8">Who governs when the person everyone trusted is dead, wounded, or absent?</p>
<p class="font_8">And what good is a constitution if nobody obeys it when they are afraid?</p>
<p class="font_8">The struggle culminates at Kite Ford, where a civilian congress must survive siege, bloodshed, and three days of pressure without surrendering itself to military government.</p>
<p class="font_8"><strong>Blood Charter</strong> is Book Six of <em>The Empire</em>, completing the second trilogy of the nine-book adult epic fantasy saga.</p>
<p class="font_8">For readers who enjoy political fantasy, constitutional conflict, succession crises, military tension, morally complicated institutions, found family, grief, romance, armed diplomacy, and stories where the most important battle may be over who has the lawful right to give an order.</p>
<p class="font_8"><strong>Blood can remember a ruler.<br>
A charter must survive without one.</strong></p>', '689', 'Fantasy / Epic / Historical / Military ↗', 'Preorder / scheduled', '2027-03-01T05:00:00Z', '9798174548770', 'eBook (preorder); Paperback; Hardcover', 'https://www.amazon.com/dp/B0HK1C8MWW', 'https://www.amazon.com/dp/B0HK1C8MWW', '', 0, 0, 0, 0, 0, 0, '', '', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('a43bea6a-fe74-4c4f-98f4-94a5af1fcd6c', 'WE, THE WATCHMEN', 'A Message to the Public and the Police From one who has served both', 'R.E. Smith', '', '', 'Before policing became a profession, ordinary people kept the peace by guarding their streets and answering the call to protect one another. We, The Watchmen traces this tradition from ancient English peace-pledges to modern policing, examining the public’s role in law, duty, and community safety.', '<p class="font_8">Before police were a profession, keeping the peace belonged to the people.</p>
<p class="font_8">Long before patrol cars, badges, radios, and blue uniforms, ordinary citizens stood watch over their own streets. They answered the hue and cry. They guarded the gates. They were bound by law and duty to protect one another because there was no one else coming.</p>
<p class="font_8">We, The Watchmen traces that forgotten history from ancient English peace-pledges and watchmen, through the Bow Street Runners, Robert Peel’s New Police, August Vollmer’s professional reforms, community policing, broken-windows theory, and the fractured public debate that followed George Floyd’s death. Along the way, R. E. Smith examines one hard truth: policing was never meant to belong to the badge alone.</p>
<p class="font_8">Written by one who has served both the public and the police, this book is not an attack on law enforcement, and it is not a blind defense of it. It is a plainspoken call for both sides to remember the old arrangement: the police are drawn from the public, and the public still carries responsibility for the peace of its own neighborhoods.</p>
<p class="font_8">At a time when trust is thin, anger is loud, and the line between citizen and officer feels more divided than ever, We, The Watchmen offers a grounded, historical, and deeply personal argument for restoring what should never have been lost.</p>
<p class="font_8">The badge may carry authority.</p>
<p class="font_8">But the people carry the power.</p>', '97', 'Law Enforcement / Social Sciences / Criminology / Crime & Criminals', 'Available', '2026-07-03T04:00:00Z', '9798185378847', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H7JXGNCH', 'https://www.amazon.com/dp/B0H7JXGNCH', '', 0, 1, 1, 1, 0, 0, '14.95', '6.46', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with the book title, format (paperback or hardcover), quantity, and the name or message you would like included, if any. Signed-copy prices are the listed paperback or hardcover price plus $2. Shipping is additional and will be confirmed with the total before payment. Please wait for confirmation of availability and total cost before sending payment.</p>', 'resmithauthor@gmail.com', '', ''),
('a5413cb3-ea4a-404d-a191-bf36cde47d84', 'Ravenscar', 'The Black Wake', 'R.E. Smith', '', '', 'A dead ship drifts into Stonegate with no crew, a black star burned into its sail, a dragon scale in the captain’s cabin, and a warning not to let it hear bells. Captain Morwen Ravenscar must face a message from beyond the known world and the losses that still haunt her.', 'A dead ship drifts into Stonegate at dawn. No crew. No sound. No gulls circling above it. Only a black star burned through its sail, a dragon scale in the captain’s cabin, and a warning carved into wood: Do not let it hear bells. Captain Morwen Ravenscar has survived war, fire, grief, and the kind of loss that leaves teeth marks on the soul. Then the dead ship arrives, carrying a ruined survivor and a message from beyond every honest map. West of the Shatterchain, beneath waters sailors were never meant to cross, something ancient is waking. To stop it, Morwen must take the Nailwife and sail into the Black Wake, a cursed road of dark water, old names, drowned bells, and things that remember the taste of men. Ravenscar: The Black Wake is a dark nautical fantasy of grief, loyalty, sacrifice, dragons, ancient powers, and the price paid by those who stand between the living world and the deep.', '554', 'Fantasy / Dark Nautical Fantasy', 'Available', '2026-06-05T04:00:00Z', '9798180085672', 'eBook; Paperback; Hardcover', 'https://www.amazon.com/dp/B0H48C38H9', 'https://www.amazon.com/dp/B0H48C38H9', '', 0, 1, 1, 1, 0, 0, '20.38', '12.63', '<p class="font_8">To order a book directly, email resmithauthor@gmail.com with the book title, requested format (paperback or hardcover), quantity, and your shipping address. Please include any special instructions. I will confirm availability, shipping cost, total price, and payment arrangements before the order is finalized. Do not send payment until the total is confirmed.</p>', 'resmithauthor@gmail.com', '<p>To request a signed copy, email resmithauthor@gmail.com with 